import { ok, fail } from './result.js';
import { getCustomer, normalizeId } from './customers.js';
import { balanceDue } from './payments.js';

/**
 * Generate a customer statement showing outstanding invoices.
 * @param {string} customerId
 * @param {Array<Object>} invoices All invoices in the system
 * @param {string} asOf Date in YYYY-MM-DD format
 * @returns {{ ok: true, value: { customerId: string, invoices: Array, totalDue: number } } | { ok: false, error: string }}
 */
export function statement(customerId, invoices, asOf) {
  // Normalize customer ID
  const normalizedCustomerId = normalizeId(customerId);

  // Validate customer exists
  const customerResult = getCustomer(normalizedCustomerId);
  if (!customerResult.ok) return customerResult;

  // Filter invoices for this customer that are issued/partially_paid and on or before asOf
  const relevantInvoices = invoices.filter(
    (invoice) =>
      invoice.customerId === normalizedCustomerId &&
      (invoice.status === 'issued' || invoice.status === 'partially_paid') &&
      invoice.issueDate <= asOf
  );

  // Map to statement format
  const statementInvoices = relevantInvoices
    .map((invoice) => ({
      number: invoice.number,
      issueDate: invoice.issueDate,
      dueDate: invoice.dueDate,
      total: invoice.voucher
        ? invoice.total - 0 + invoice.voucher.amount // Recalculate to get subtotal + tax - payments, not considering voucher
        : invoice.total,
      due: balanceDue(invoice),
    }))
    .sort((a, b) => a.issueDate.localeCompare(b.issueDate));

  // Get total from invoiceTotals for accurate total (with voucher already applied)
  const statementInvoices2 = relevantInvoices
    .map((invoice) => {
      const due = balanceDue(invoice);
      const total = due + (invoice.payments ? invoice.payments.reduce((sum, p) => sum + p.amount, 0) : 0);
      return {
        number: invoice.number,
        issueDate: invoice.issueDate,
        dueDate: invoice.dueDate,
        total,
        due,
      };
    })
    .sort((a, b) => a.issueDate.localeCompare(b.issueDate));

  // Calculate total due
  const totalDue = statementInvoices2.reduce((sum, inv) => sum + inv.due, 0);

  return ok({
    customerId: normalizedCustomerId,
    invoices: statementInvoices2,
    totalDue,
  });
}

